function brokenCalc(startValue, target) {
  // Forward view: try each number k of doublings. A decrement made while i doublings are
  // still to come lowers the final value by 2^i, so the decrements needed to remove
  // diff = startValue * 2^k - target are as many 2^k's as fit, plus the binary 1-bits of the rest.
  let best = Infinity;
  let k = 0;
  let tries = 0;
  for (let top = startValue; tries < 4; top *= 2, k++) {
    if (top < target) continue;
    tries++;
    const diff = top - target;
    const unit = 2 ** k;
    let ops = k + Math.floor(diff / unit);
    let rest = diff % unit;
    while (rest > 0) { ops += rest % 2; rest = Math.floor(rest / 2); }
    best = Math.min(best, ops);
  }
  return best;
}

