function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const r = rand();
    if (r < 0.4) return [int(1, 1000), int(1, 1e9)];
    if (r < 0.6) return [int(1, 1e9), int(1, 1000)];
    return [int(1, 1e9), int(1, 1e9)];
  }
  if (rand() < 0.5) return [int(1, 12), int(1, 80)];
  return [int(1, 60), int(1, 60)];
}
